    s.results.push(r); s.result = r; s.sidx++; s.done = s.sidx >= s.lines.length; s.ev.push({ k: 'station', r: r });
    if (why === 'stop') { s.phase = 'dwell'; s.v = 0; s.thr = 0; s.brk = 1; }
